def build_network(self) -> None:
    params_global = self.param_registry.get_params("global")
    N = len(self.state["persons"])
    k = int(params_global.get("average_degree", 8))
    net_type = str(params_global.get("network_type", "small_world"))
    hom = float(params_global.get("homophily_strength", 0.0))
    rewiring_p = float(params_global.get("rewiring_probability", 0.05))
    rng = self.rng
    network: Dict[int, List[int]] = {i: [] for i in range(N)}

    def add_edge(a,b):
        if b not in network[a]: network[a].append(b)
        if a not in network[b]: network[b].append(a)

    if net_type == "er":
        p = min(1.0, k / max(1, N-1))
        for i in range(N):
            for j in range(i+1, N):
                if rng.random() < p: add_edge(i,j)
    elif net_type == "scale_free":
        targets = [0]
        degrees = [1]
        for i in range(1, N):
            probs = np.array(degrees, dtype=float) / np.sum(degrees)
            m = max(1, k//2)
            chosen = set(rng.choice(len(targets), size=min(m, len(targets)), replace=False, p=probs))
            for t in chosen: add_edge(i, targets[t])
            targets.append(i); degrees.append(len(network[i]) or 1)
            for t in chosen: degrees[t] = len(network[targets[t]]) or 1
    else:
        k = max(2, k if k % 2 == 0 else k + 1)
        for i in range(N):
            for j in range(1, k // 2 + 1):
                add_edge(i, (i + j) % N)
        # homophilous rewiring
        groups = [p.get("demographics_group", "A") for p in self.state["persons"]]
        for i in range(N):
            for j_idx, nb in enumerate(list(network[i])):
                if rng.random() < rewiring_p:
                    # prefer same-group with prob (0.5+0.5*hom)
                    same_pref = 0.5 + 0.5 * hom
                    candidates = list(range(N))
                    rng.shuffle(candidates)
                    for cand in candidates:
                        if cand == i or cand in network[i]: continue
                        if (groups[cand] == groups[i] and rng.random() < same_pref) or (groups[cand] != groups[i] and rng.random() < (1.0 - same_pref)):
                            network[i].remove(nb)
                            if i in network[nb]: network[nb].remove(i)
                            add_edge(i, cand)
                            break
    self.state["network"] = network
